    if limit > 0:
        heat_factor = (limit - heat) / limit
    else:
        heat_factor = 0
    gain = 0.5 * heat_factor  # Reduce gain as heat approaches limit

    # Apply thrust with proportional control
    f1 = gain * dx
    f2 = gain * dy
